//! Reference pages rendered from the code itself: clap's command tree, the
//! built-in provider table, the tool registry, and the slash-command
//! catalog. Output is deterministic (fixed terminal width, ordered maps).

use clap::CommandFactory as _;

const HEADER: &str =
    "<!-- GENERATED by `UPDATE_DOCS=1 cargo test doc_sync` — do not edit by hand. -->\n";

/// One Markdown table cell: pipes escaped, whitespace collapsed.
fn cell(text: &str) -> String {
    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace('|', "\\|")
        .replace('<', "&lt;")
}

fn code(text: &str) -> String {
    format!("`{}`", text.replace('`', "'"))
}

pub(super) fn cli_reference() -> String {
    let mut cmd = crate::Cli::command().term_width(88);
    let usage = cmd.render_help().to_string();
    let mut out = format!(
        "{HEADER}\n# CLI Reference\n\nEvery `gg` flag, generated from the argument parser.\n\n"
    );
    out.push_str("## Help output\n\n```text\n");
    out.push_str(usage.trim_end());
    out.push_str("\n```\n\n## Flags and arguments\n\n");
    out.push_str("| Argument | Description | Default | Values |\n|---|---|---|---|\n");
    for arg in cmd.get_arguments() {
        let id = arg.get_id().as_str();
        if id == "help" || id == "version" {
            continue;
        }
        let mut names = Vec::new();
        if let Some(short) = arg.get_short() {
            names.push(format!("-{short}"));
        }
        if let Some(long) = arg.get_long() {
            names.push(format!("--{long}"));
        }
        let takes_value = arg.get_action().takes_values();
        let value: Vec<String> = arg
            .get_value_names()
            .filter(|_| takes_value)
            .map(|v| v.iter().map(|s| format!("<{s}>")).collect())
            .unwrap_or_default();
        let mut label = if names.is_empty() {
            value.join(" ")
        } else {
            names.join(", ")
        };
        if !names.is_empty() && !value.is_empty() {
            label = format!("{label} {}", value.join(" "));
        }
        let default: Vec<String> = arg
            .get_default_values()
            .iter()
            .filter(|_| takes_value)
            .map(|v| v.to_string_lossy().into_owned())
            .collect();
        let possible: Vec<String> = arg
            .get_possible_values()
            .iter()
            .map(|v| v.get_name().to_string())
            .collect();
        out.push_str(&format!(
            "| {} | {} | {} | {} |\n",
            code(&label),
            cell(&arg.get_help().map(|h| h.to_string()).unwrap_or_default()),
            if default.is_empty() {
                String::new()
            } else {
                code(&default.join(", "))
            },
            if possible.is_empty() {
                String::new()
            } else {
                code(&possible.join(", "))
            },
        ));
    }
    out
}

pub(super) fn providers_reference() -> String {
    let providers = crate::config::providers::builtin_providers();
    let mut out = format!(
        "{HEADER}\n# Providers & Models\n\nBuilt-in provider presets, generated from the provider table. `zai-coding-plan` is an alias for `glm-coding-plan`. Custom providers are covered in [Configuration](../guide/configuration.md).\n\n"
    );
    out.push_str("| Provider | Default model | Wire API | API key variable | Base URL | Max tokens | Context window |\n|---|---|---|---|---|---|---|\n");
    for p in providers.values() {
        out.push_str(&format!(
            "| {} | {} | {} | {} | {} | {} | {} |\n",
            code(&p.name),
            code(&p.default_model),
            code(p.api.as_str()),
            p.api_key_env
                .as_deref()
                .map_or("none (local)".to_string(), code),
            code(&p.base_url),
            p.max_tokens,
            p.context_window,
        ));
    }
    for p in providers.values() {
        out.push_str(&format!("\n## {}\n\n", p.name));
        out.push_str("| Model | Wire API | Context window | Max tokens | Replays reasoning | Base URL |\n|---|---|---|---|---|---|\n");
        for spec in &p.models {
            let ep = p.resolve(Some(&spec.id));
            let default = if spec.id == p.default_model {
                " (default)"
            } else {
                ""
            };
            out.push_str(&format!(
                "| {}{default} | {} | {} | {} | {} | {} |\n",
                code(&spec.id),
                code(ep.api.as_str()),
                ep.context_window,
                ep.max_tokens,
                ep.replay_reasoning.as_str(),
                code(&ep.base_url),
            ));
        }
    }
    out
}

fn schema_type(prop: &serde_json::Value) -> String {
    let ty = prop["type"].as_str().unwrap_or("any");
    match (ty, prop["items"]["type"].as_str()) {
        ("array", Some(item)) => format!("array of {item}"),
        _ => ty.to_string(),
    }
}

pub(super) fn tools_reference() -> String {
    let registry = crate::agent::tools::default_registry(std::path::PathBuf::from("."), 30);
    let mut out = format!(
        "{HEADER}\n# Built-in Tools\n\nThe tool surface the model sees, generated from the registry (advertisement order). Behaviour and limits are explained in [Tools](../guide/tools.md).\n\n"
    );
    out.push_str("| Tool | Description |\n|---|---|\n");
    for tool in registry.tools() {
        out.push_str(&format!(
            "| {} | {} |\n",
            code(tool.name()),
            cell(tool.description())
        ));
    }
    for tool in registry.tools() {
        let schema = tool.schema();
        out.push_str(&format!(
            "\n## `{}`\n\n{}\n\n",
            tool.name(),
            tool.description()
        ));
        let required: Vec<&str> = schema["required"]
            .as_array()
            .map(|a| a.iter().filter_map(|v| v.as_str()).collect())
            .unwrap_or_default();
        out.push_str("| Parameter | Type | Required | Description |\n|---|---|---|---|\n");
        if let Some(props) = schema["properties"].as_object() {
            for (name, prop) in props {
                out.push_str(&format!(
                    "| {} | {} | {} | {} |\n",
                    code(name),
                    schema_type(prop),
                    if required.contains(&name.as_str()) {
                        "yes"
                    } else {
                        "no"
                    },
                    cell(prop["description"].as_str().unwrap_or("")),
                ));
            }
        }
    }
    out
}

pub(super) fn commands_reference() -> String {
    let mut out = format!(
        "{HEADER}\n# TUI Slash Commands\n\nGenerated from the command catalog that drives the `/` suggestion popup.\n\n"
    );
    out.push_str("| Command | Arguments | Description |\n|---|---|---|\n");
    for (name, args, description) in crate::tui::suggest::BUILTINS {
        out.push_str(&format!(
            "| {} | {} | {} |\n",
            code(name),
            cell(args).trim(),
            cell(description),
        ));
    }
    out.push_str("\n`/exit` is a hidden alias for `/quit`. Any `~/.gg/prompts/*.md` template also becomes a `/name` command, and `!cmd` / `!!cmd` run a shell line (see [Interactive TUI](../guide/tui.md)).\n");
    out
}
